-- ================================================================\n-- Migration: 20251227_add_stripe_refund_id_to_trades.sql\n-- Module: MODULE-12 ADMIN-V2-009 - Admin Trade Management\n-- Description: Adds missing stripe_refund_id column to trades table\n-- ================================================================\n\n-- Add stripe_refund_id to trades table\nALTER TABLE trades\nADD COLUMN IF NOT EXISTS stripe_refund_id TEXT;\n\nCOMMENT ON COLUMN trades.stripe_refund_id IS 'Stripe Refund ID for cancelled trades (audit trail)';\n\n-- Verification Query:\n-- SELECT column_name FROM information_schema.columns WHERE table_name = 'trades' AND column_name = 'stripe_refund_id';\n